def comps(g):
    seen=set(); res=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==0 and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    x,y=st.pop(); c.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b]==0 and (a,b) not in seen:
                            seen.add((a,b)); st.append((a,b))
                res.append(c)
